"""Write the str.casefold table and the hard-case fixture (Python 3.12)."""
import hashlib, json, sys, unicodedata
out_table, out_fixture = sys.argv[1], sys.argv[2]
rows = []
for cp in range(0x110000):
    if 0xD800 <= cp <= 0xDFFF:
        continue
    c = chr(cp)
    f = c.casefold()
    if f != c:
        rows.append("%X\t%s" % (cp, " ".join("%X" % ord(x) for x in f)))
with open(out_table, "w") as fh:
    fh.write("# Python %s str.casefold, unicodedata %s; generated by tests/fixtures/capture/gen_casefold.py\n" % (sys.version.split()[0], unicodedata.unidata_version))
    fh.write("\n".join(rows) + "\n")
h = hashlib.sha256()
for cp in range(0x110000):
    if 0xD800 <= cp <= 0xDFFF:
        continue
    h.update(chr(cp).casefold().encode("utf-8") + b"\0")
hard = ["Straße", "STRASSE", "ẞ", "ſ", "ΣΑΣ", "ὈΔΥΣΣΕΎΣ", "ﬃ", "ﬅ", "ŉ", "ǰ", "ΐ", "İstanbul", "ı",
        "Ꭰ", "ꭰ", "Ⴀ", "ᲀ", "𐐀", "𞤀", "ǅ", "ﬓ", "ẚ", "ᾈ", "ᾼ", "K", "Å", "µ", "ͅ", "Ǉ",
        "Bêta.ÜNÏ@EXÄMPLE.TEST", "ALPHA@Example.Test", "mañana@FOO.ES", "ǈ", "ꞵ", "Ꞵ", "ẞß"]
with open(out_fixture, "w") as fh:
    json.dump({"python": sys.version.split()[0], "unidata": unicodedata.unidata_version,
               "rows": len(rows), "all_codepoints_sha256": h.hexdigest(),
               "cases": [[s, s.casefold()] for s in hard]}, fh, indent=2, ensure_ascii=False)
    fh.write("\n")
print(len(rows), unicodedata.unidata_version)
